for(let i=0;i<10;i++){let x=rand(-16,16),z=rand(-5,8);if(Math.abs(x)<3&&z>2)z-=6;makeVoxelPerson(x,z,true)}
const raycaster=new THREE.Raycaster();raycaster.far=100;const forward=new THREE.Vector3();const up=new THREE.Vector3(0,1,0);const tmp=new THREE.Vector3();
function aimRay(){camera.getWorldDirection(forward);raycaster.set(camera.getWorldPosition(tmp),forward);raycaster.far=90;return raycaster}
function showToast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove('show'),1700)}
function spark(pos,color='#ffd37a',count=8,scale=1){for(let i=0;i<count;i++){const m=new THREE.Mesh(boxGeo,mat(color,.6));m.scale.setScalar(rand(.04,.12)*scale);m.position.copy(pos);m.rotation.set(rand(0,6),rand(0,6),rand(0,6));scene.add(m);effects.push({mesh:m,vel:new THREE.Vector3(rand(-3,3),rand(.4,4),rand(-3,3)).multiplyScalar(scale),life:rand(.35,.8),gravity:6})}}
function makeShard(part,origin,force=1){const clone=new THREE.Mesh(part.geometry,part.material);clone.position.copy(part.getWorldPosition(new THREE.Vector3()));clone.quaternion.copy(part.getWorldQuaternion(new THREE.Quaternion()));clone.scale.copy(part.getWorldScale(new THREE.Vector3()));scene.add(clone);debris.push({mesh:clone,vel:new THREE.Vector3(rand(-2,2),rand(1,5),rand(-2,2)).add(forward.clone().multiplyScalar(force*rand(.5,1.8))),spin:new THREE.Vector3(rand(-6,6),rand(-6,6),rand(-6,6)),life:18,grounded:false});return clone}
function breakPerson(person,force=1){const d=person.userData;if(!d.alive)return;d.alive=false;d.ragdoll=1;for(const p of d.parts){p.visible=false;makeShard(p,person.position,force)}spark(person.position.clone().add(new THREE.Vector3(0,1,0)),'#f1bd76',13,.8);showToast(d.civilian?'SUBJECT DOWN — TEST EVENT':'TARGET DISABLED');setTimeout(()=>{if(person.parent)person.parent.remove(person);targets=targets.filter(t=>t!==person)},19000)}
function damageTarget(hit,force=1){let obj=hit.object;while(obj&&!obj.userData?.parts)obj=obj.parent;if(!obj)return false;const d=obj.userData;if(!d.alive)return false;d.hp-=weapon==='KAT'?42:weapon==='DEAGLE'?55:weapon==='FLAME'?18:weapon==='GRENADE'?90:34;d.stagger=Math.max(d.stagger,.7);d.panic=2.8;const dir=forward.clone().multiplyScalar(force);obj.position.addScaledVector(dir,.12);spark(hit.point,weapon==='FLAME'?'#ff8c35':'#f1c36d',7,.6);if(d.hp<=0)breakPerson(obj,force);return true}
function impact(){const ray=aimRay();const hits=ray.intersectObjects([...targets,...decor],true);if(hits.length){const h=hits[0];if(!damageTarget(h,weapon==='DEAGLE'?1.5:1)){spark(h.point,weapon==='FLAME'?'#ff7b32':'#d6ceab',6,.55);const o=h.object;if(o.parent===world&&o.geometry===boxGeo&&o.scale.y>1){o.material=mat('#827b64');o.userData.damage=(o.userData.damage||0)+1;if(o.userData.damage>4){o.visible=false;spark(h.point,'#c7bf9c',18,1)}}}}
 else {const p=camera.getWorldPosition(tmp).add(forward.clone().multiplyScalar(36));spark(p,'#c7c69a',4,.3)}}
function fire(){if(fireCooldown>0)return;if(weapon==='GRENADE'){const dir=camera.getWorldDirection(new THREE.Vector3());const orb=new THREE.Mesh(new THREE.IcosahedronGeometry(.2,1),mat('#d7aa4a'));orb.position.copy(camera.getWorldPosition(new THREE.Vector3())).add(dir.multiplyScalar(.8));scene.add(orb);debris.push({mesh:orb,vel:dir.multiplyScalar(14).add(new THREE.Vector3(0,4,0)),spin:new THREE.Vector3(2,4,1),life:2.1,grenade:true});fireCooldown=.8;spark(gun.getWorldPosition(new THREE.Vector3()),'#ffc75e',5,.5);return}
 if(weapon==='KAT'){fireCooldown=.55;const ray=aimRay();const hits=ray.intersectObjects(targets,true);if(hits.length&&hits[0].distance<3.2)damageTarget(hits[0],2);spark(camera.getWorldPosition(new THREE.Vector3()).add(forward.clone().multiplyScalar(2)),'#fff0bb',6,.4);return}
 if(ammo<=0){showToast('MAGAZINE EMPTY — RELOAD');return}ammo--;fireCooldown=weapon==='FLAME'?.11:weapon==='DEAGLE'?.32:.14;impact();gun.position.z=-.49;setTimeout(()=>gun.position.z=-.62,55);const muzzle=gun.getWorldPosition(new THREE.Vector3());spark(muzzle,weapon==='FLAME'?'#ff7839':'#ffd36b',4,.35);if(weapon==='FLAME'){const dir=camera.getWorldDirection(new THREE.Vector3());for(let i=0;i<3;i++){const p=muzzle.clone().add(dir.clone().multiplyScalar(i*.5));spark(p,'#ff7134',3,.5)}}if(weapon==='DEAGLE')ammo=Math.max(0,ammo)}
function reload(){if(ammo>=maxAmmo)return;showToast('RELOADING…');setTimeout(()=>{ammo=maxAmmo;showToast('MAGAZINE READY')},900)}
function burst(center,radius=8,power=12){spark(center,'#ffb35b',38,1.8);const flash=new THREE.PointLight('#ff9d47',22,18);flash.position.copy(center);scene.add(flash);setTimeout(()=>scene.remove(flash),260);for(const t of targets){if(!t.userData.alive)continue;const d=t.position.distanceTo(center);if(d<radius){t.userData.hp-=Math.round((1-d/radius)*150);t.userData.stagger=2;t.position.add(t.position.clone().sub(center).normalize().multiplyScalar(.8));if(t.userData.hp<=0)breakPerson(t,power)}}for(const item of debris){const d=item.mesh.position.distanceTo(center);if(d<radius)item.vel.add(item.mesh.position.clone().sub(center).normalize().multiplyScalar(power*(1-d/radius)))}for(const o of decor){if(o.position.distanceTo(center)<radius*.6&&o.userData?.breakable)o.visible=false}}
function doGod(action){const ray=aimRay(),hit=ray.intersectObjects([...targets,...decor],true)[0],point=hit?hit.point:camera.getWorldPosition(new THREE.Vector3()).add(forward.clone().multiplyScalar(9));if(action==='grab'){grabMode=!grabMode;showToast(grabMode?'GRAB TOOL ARMED — CLICK OBJECT':'GRAB TOOL OFF');return}if(action==='push'||action==='lightning'){for(const t of targets)if(t.position.distanceTo(point)<10){t.position.add(t.position.clone().sub(point).normalize().multiplyScalar(1.3));t.userData.stagger=1.5;if(action==='lightning')spark(t.position.clone().add(new THREE.Vector3(0,1,0)),'#b693ff',18,1);if(action==='lightning'){t.userData.hp-=80;if(t.userData.hp<=0)breakPerson(t,2)}}spark(point,action==='push'?'#b9d1c5':'#b693ff',22,1);return}if(action==='blast'){burst(point,9,15);showToast('KINETIC EVENT');return}if(action==='fire'){spark(point,'#ff7737',22,1.3);showToast('FLARE DEPLOYED');return}if(action==='slow'){slow=!slow;showToast(slow?'TIME DILATION ON':'TIME NORMAL');return}if(action==='spawn'){makeVoxelPerson(point.x+rand(-2,2),point.z+rand(-2,2),true);showToast('SUBJECT ENTERED FIELD');return}if(action==='clean'){cleanup();return}if(action==='map'){changeMap();return}if(action==='eyes'){eyes=!eyes;showToast(eyes?'LASER EYES ONLINE':'LASER EYES OFFLINE')}}
function cleanup(){for(const t of targets)if(t.parent)t.parent.remove(t);targets=[];for(const d of debris)scene.remove(d.mesh);debris=[];effects.forEach(e=>scene.remove(e.mesh));effects=[];showToast('FIELD CLEANED')}

